 object Call(string path,string method,object body,bool auth=true){if(auth&&DateTime.UtcNow>=expires){var session=(Dictionary<string,object>)Call("/auth/v1/token?grant_type=refresh_token","POST",new{refresh_token=refresh},false);Session(session);}using(var r=new HttpRequestMessage(new HttpMethod(method),Url+path)){r.Headers.Add("apikey",Key);r.Headers.Add("Authorization","Bearer "+(auth?token:Key));if(body!=null)r.Content=new StringContent(json.Serialize(body),Encoding.UTF8,"application/json");using(var response=http.SendAsync(r).GetAwaiter().GetResult()){string text=response.Content.ReadAsStringAsync().GetAwaiter().GetResult();object value=text.Length==0?null:json.DeserializeObject(text);if(!response.IsSuccessStatusCode){var error=value as Dictionary<string,object>;string message=error!=null&&error.ContainsKey("message")?Convert.ToString(error["message"]):error!=null&&error.ContainsKey("msg")?Convert.ToString(error["msg"]):"Falha na conexão online.";if(message.Contains("Invalid login credentials"))message="E-mail ou senha recusados. Use a mesma conta do Videira Site.";throw new Exception(message);}return value;}}}
