 public static Dictionary<string,object> Snapshot(DataSet data){var tables=new Dictionary<string,object>();foreach(DataTable table in data.Tables){var columns=table.Columns.Cast<DataColumn>().Select(c=>new{name=c.ColumnName,type=c.DataType==typeof(DateTime)?"date":c.DataType==typeof(bool)?"bool":c.DataType==typeof(int)?"int":c.DataType==typeof(decimal)?"number":"text",default_value=c.DefaultValue==DBNull.Value?null:c.DefaultValue}).ToArray();var rows=table.Rows.Cast<DataRow>().Where(r=>r.RowState!=DataRowState.Deleted).Select(r=>table.Columns.Cast<DataColumn>().ToDictionary(c=>c.ColumnName,c=>r[c]==DBNull.Value?null:c.DataType==typeof(DateTime)?(object)((DateTime)r[c]).ToString("o"):r[c])).ToArray();tables[table.TableName]=new{columns=columns,rows=rows};}return new Dictionary<string,object>{{"format",1},{"tables",tables}};}
